<template>
  <div class="app-container pipeline-page pipeline-template-page">
    <div class="pipeline-page-head"><div><span class="pipeline-eyebrow">TEMPLATE CENTER</span><h1>模板管理</h1><p class="summary">维护科研报告、科技项目填报表和日报周月报的结构、字段、样式与版本。</p></div><div class="pipeline-head-actions"><el-button type="primary" :icon="Plus" @click="createTemplate">新建模板</el-button></div></div>
    <div class="template-layout">
      <aside class="template-categories"><button v-for="category in categories" :key="category.name" type="button" :class="{ 'is-active': activeCategory === category.value }" @click="activeCategory = category.value"><component :is="category.icon" /><span>{{ category.name }}</span><b>{{ countCategory(category.value) }}</b></button></aside>
      <main v-loading="loading"><div class="template-toolbar"><el-input v-model="keyword" :prefix-icon="Search" clearable placeholder="搜索模板名称、用途或版本" /><el-select v-model="status"><el-option label="全部状态" value="all" /><el-option label="已发布" value="published" /><el-option label="草稿" value="draft" /><el-option label="已停用" value="disabled" /></el-select></div><div class="template-grid"><article v-for="item in filteredTemplates" :key="item.id"><div class="template-preview" :style="{ '--template-color': item.color }"><span>{{ item.code }}</span><div><i></i><i></i><i></i><i></i></div><b>{{ item.type }}</b></div><div class="template-body"><div><el-tag :type="statusTag(item.status)" size="small" effect="plain">{{ statusLabel(item.status) }}</el-tag><small>{{ item.version }}</small></div><h3>{{ item.name }}</h3><p>{{ item.description }}</p><dl><div><dt>最近更新</dt><dd>{{ item.updatedAt }}</dd></div><div><dt>使用次数</dt><dd>{{ item.usage }}</dd></div></dl><footer><el-button link type="primary" @click="editTemplate(item)">编辑</el-button><el-button link @click="previewTemplate(item)">预览</el-button><el-dropdown><el-button link><MoreFilled /></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="item.status !== 'published'" @click="publishTemplate(item)">发布版本</el-dropdown-item><el-dropdown-item v-if="item.status === 'published'" divided @click="retireTemplate(item)">停用模板</el-dropdown-item></el-dropdown-menu></template></el-dropdown></footer></div></article></div></main>
    </div>
    <el-drawer v-model="editorVisible" :title="editingTemplate?.id ? '编辑模板' : '新建模板'" size="640px"><el-form label-position="top" :model="form"><div class="template-form-grid"><el-form-item label="模板名称"><el-input v-model="form.name" /></el-form-item><el-form-item label="模板编码"><el-input v-model="form.code" :disabled="Boolean(editingTemplate)" /></el-form-item><el-form-item label="模板类型"><el-select v-model="form.category"><el-option label="科研报告" value="research" /><el-option label="日报周月报" value="digest" /><el-option label="项目填报表" value="project" /></el-select></el-form-item><el-form-item label="报告类型"><el-input v-model="form.reportType" placeholder="例如 research-demand" /></el-form-item><el-form-item label="版本号"><el-input v-model="form.versionLabel" /></el-form-item><el-form-item label="输出格式"><el-checkbox-group v-model="form.formats"><el-checkbox value="docx">Word</el-checkbox><el-checkbox value="pdf">PDF</el-checkbox></el-checkbox-group></el-form-item><el-form-item label="模板说明" class="is-full"><el-input v-model="form.description" type="textarea" :rows="3" /></el-form-item></div><h3>章节结构</h3><div v-for="(section, index) in form.sections" :key="section.id" class="template-section-row"><Rank /><span>{{ index + 1 }}</span><el-input v-model="section.title" /><el-input-number v-model="section.words" :min="100" :max="8000" :step="100" /><el-switch v-model="section.required" active-text="必填" /><button type="button" @click="form.sections.splice(index, 1)"><Delete /></button></div><el-button class="template-add-section" @click="form.sections.push({ id: Date.now(), title: '新增章节', words: 1000, required: false })"><Plus />新增章节</el-button></el-form><template #footer><el-button @click="editorVisible = false">取消</el-button><el-button :loading="saving" @click="saveDraft">保存草稿</el-button><el-button type="primary" :loading="saving" @click="saveAndPublish">保存并发布</el-button></template></el-drawer>
  </div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { Calendar, Collection, Delete, Document, Files, MoreFilled, Plus, Rank, Search } from '@element-plus/icons-vue'
import { createPipelineTemplate, listPipelineTemplates, publishPipelineTemplate, retirePipelineTemplate, updatePipelineTemplate } from '@/api/pipeline/intelligence'

const activeCategory = ref('all')
const keyword = ref('')
const status = ref('all')
const editorVisible = ref(false)
const editingTemplate = ref(null)
const saving = ref(false)
const loading = ref(false)
const categories = [{ name: '全部模板', value: 'all', icon: Files }, { name: '科研报告', value: 'research', icon: Document }, { name: '日报周月报', value: 'digest', icon: Calendar }, { name: '项目填报表', value: 'project', icon: Collection }]
const templates = ref([])
const form = reactive({ templateKey: '', code: '', category: 'research', reportType: 'research-demand', name: '', versionLabel: 'V1.0', description: '', color: '#2764e7', formats: ['docx'], sections: [] })
const filteredTemplates = computed(() => templates.value.filter(item => (activeCategory.value === 'all' || item.category === activeCategory.value) && (status.value === 'all' || item.status === status.value || (status.value === 'disabled' && item.status === 'retired')) && (!keyword.value || `${item.name}${item.description}${item.version}`.includes(keyword.value))))
function countCategory(value) { return value === 'all' ? templates.value.length : templates.value.filter(item => item.category === value).length }
function statusTag(value) { return ({ published: 'success', draft: 'warning', retired: 'info', disabled: 'info' })[value] }
function statusLabel(value) { return ({ published: '已发布', draft: '草稿', retired: '已停用', disabled: '已停用' })[value] }
function resetForm(item = null) { Object.assign(form, { templateKey: item?.templateKey || '', code: item?.code || 'R-03', category: item?.category || 'research', reportType: item?.reportType || 'research-demand', name: item?.name || '', versionLabel: item?.version || 'V1.0', description: item?.description || '', color: item?.color || '#2764e7', formats: item?.formats?.length ? [...item.formats] : ['docx'], sections: item?.sections?.length ? item.sections.map(section => ({ ...section })) : [{ id: 1, title: '项目背景与问题分析', words: 1800, required: true }, { id: 2, title: '研究目标与主要内容', words: 2200, required: true }, { id: 3, title: '技术路线与实施方案', words: 2000, required: true }] }) }
function createTemplate() { editingTemplate.value = null; resetForm(); editorVisible.value = true }
function editTemplate(item) { editingTemplate.value = item; resetForm(item); editorVisible.value = true }
function previewTemplate(item) { ElMessage.info(`正在预览：${item.name}`) }
async function loadTemplates() { loading.value = true; try { const res = await listPipelineTemplates(); templates.value = res.data?.rows || [] } catch (error) { ElMessage.warning('模板列表暂时无法加载') } finally { loading.value = false } }
function templatePayload() { return { templateKey: form.templateKey || undefined, code: form.code, category: form.category, reportType: form.reportType, name: form.name, versionLabel: form.versionLabel, description: form.description, color: form.color, formats: form.formats, sections: form.sections } }
async function saveDraft() { if (saving.value) return; saving.value = true; try { if (editingTemplate.value) await updatePipelineTemplate(editingTemplate.value.templateKey, templatePayload()); else await createPipelineTemplate(templatePayload()); editorVisible.value = false; ElMessage.success('模板新版本已保存为草稿'); await loadTemplates() } catch (error) { ElMessage.error(error?.msg || '模板保存失败') } finally { saving.value = false } }
async function saveAndPublish() { if (saving.value) return; saving.value = true; try { const res = editingTemplate.value ? await updatePipelineTemplate(editingTemplate.value.templateKey, templatePayload()) : await createPipelineTemplate(templatePayload()); const templateKey = res.data?.templateKey || form.templateKey; await publishPipelineTemplate(templateKey); editorVisible.value = false; ElMessage.success('模板新版本已发布'); await loadTemplates() } catch (error) { ElMessage.error(error?.msg || '模板发布失败') } finally { saving.value = false } }
async function publishTemplate(item) { try { await publishPipelineTemplate(item.templateKey); ElMessage.success('模板已发布'); await loadTemplates() } catch (error) { ElMessage.error(error?.msg || '模板发布失败') } }
async function retireTemplate(item) { try { await retirePipelineTemplate(item.templateKey); ElMessage.success('模板已停用'); await loadTemplates() } catch (error) { ElMessage.error(error?.msg || '模板停用失败') } }
onMounted(loadTemplates)
</script>

<style scoped>
.template-layout { display: grid; grid-template-columns: 210px minmax(0,1fr); gap: 18px; }.template-categories { padding: 10px; border: 1px solid #e2e8f0; border-radius: 10px; align-self: start; background: #fff; }.template-categories button { width: 100%; min-height: 44px; padding: 0 11px; border: 0; border-radius: 7px; display: grid; grid-template-columns: 18px 1fr auto; gap: 9px; align-items: center; background: transparent; color: #475569; cursor: pointer; text-align: left; }.template-categories button.is-active { background: #edf3ff; color: #2764e7; }.template-categories svg { width: 16px; }.template-categories b { font-size: 11px; }
.template-toolbar { margin-bottom: 14px; display: grid; grid-template-columns: minmax(260px,1fr) 140px; gap: 10px; }.template-grid { display: grid; grid-template-columns: repeat(3,minmax(0,1fr)); gap: 15px; }.template-grid article { border: 1px solid #e2e8f0; border-radius: 11px; overflow: hidden; background: #fff; }.template-preview { height: 145px; padding: 18px; position: relative; background: linear-gradient(145deg, color-mix(in srgb,var(--template-color),#fff 88%),#f8fafc); }.template-preview > span { color: var(--template-color); font-size: 11px; font-weight: 800; }.template-preview > div { width: 110px; margin: 18px auto 0; padding: 16px; border-top: 4px solid var(--template-color); background: #fff; box-shadow: 0 5px 15px rgba(15,23,42,.1); }.template-preview i { height: 3px; margin-bottom: 7px; display: block; background: #dbe3ed; }.template-preview i:nth-child(2){width:78%}.template-preview i:nth-child(3){width:90%}.template-preview i:nth-child(4){width:60%}.template-preview > b { position: absolute; right: 14px; bottom: 12px; color: #64748b; font-size: 10px; }.template-body { padding: 17px; }.template-body > div { display: flex; justify-content: space-between; }.template-body small { color: #64748b; }.template-body h3 { margin: 13px 0 7px; font-size: 15px; }.template-body p { height: 38px; margin: 0; overflow: hidden; color: #64748b; font-size: 11px; line-height: 1.7; }.template-body dl { margin: 14px 0; }.template-body dl div { padding: 4px 0; display: flex; justify-content: space-between; color: #64748b; font-size: 10px; }.template-body dd { margin: 0; color: #334155; }.template-body footer { padding-top: 10px; border-top: 1px solid #edf1f6; display: flex; align-items: center; }
.template-form-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 0 14px; }.template-form-grid .is-full { grid-column: 1/-1; }.template-section-row { min-height: 52px; display: grid; grid-template-columns: 18px 24px 1fr 80px 28px; gap: 8px; align-items: center; }.template-section-row > svg { width: 14px; color: #94a3b8; }.template-section-row > button { border: 0; background: transparent; color: #94a3b8; cursor: pointer; }.template-section-row > button svg { width: 15px; }.template-add-section { width: 100%; margin-top: 10px; }
@media (max-width: 1100px){.template-grid{grid-template-columns:repeat(2,1fr)}}@media (max-width:760px){.template-layout{grid-template-columns:1fr}.template-categories{display:grid;grid-template-columns:repeat(2,1fr)}.template-grid{grid-template-columns:1fr}.template-toolbar,.template-form-grid{grid-template-columns:1fr}}
</style>
